INSERT INTO `genres` (`id`, `genre_name`, `slug`, `description`, `is_menu`) VALUES
(24, 'Blackmail', 'blackmail', 'Thể loại truyện có cốt truyện xoay quanh việc tống tiền hoặc đe dọa bằng bí mật cá nhân.', 1),
(25, 'Lỗ Nhị', 'lo-nhi', '', 0),
(26, 'Milfs', 'milfs', 'Thể loại tập trung vào nhân vật nữ là những người mẹ hoặc phụ nữ trưởng thành, quyến rũ.', 0),
(27, 'Nhóm', 'nhom', '', 0),
(28, 'Shotacon', 'shotacon', 'Thể loại tập trung vào các nhân vật nam nhỏ tuổi hoặc có ngoại hình trẻ con.', 0),
(29, 'Stockings', 'stockings', 'Thể loại nhấn mạnh vào trang phục tất dài, tất đùi của nhân vật.', 1),
(30, 'Truyện Ngắn', 'truyen-ngan', '', 0),
(31, 'Vếu To', 'veu-to', '', 0),
(32, '18+', 'nguoi-lon-18', 'Thể loại chứa nội dung người lớn, nhạy cảm hoặc bạo lực không dành cho trẻ vị thành niên.', 0),
(33, 'Bối Cảnh Phương Tây', 'boi-canh-phuong-tay', '', 0),
(34, 'Chênh Lệch Thân Phận', 'chenh-lech-than-phan', '', 0),
(35, 'Chiếm Hữu/Ghen Tuông', 'chiem-huu-ghen-tuong', '', 0),
(36, 'Hiểu Lầm', 'hieu-lam', '', 0),
(37, 'Học Viện', 'hoc-vien', '', 0),
(38, 'Mối Tình Đầu', 'moi-tinh-dau', '', 0),
(39, 'Nam Chính Chiếm Hữu', 'nam-chinh-chiem-huu', '', 0),
(40, 'Novel', 'novel', 'Thể loại truyện chữ, tiểu thuyết dạng văn xuôi.', 0),
(41, 'Thuần Khiết', 'thuan-khiet', '', 0),
(42, 'Artist', 'artist', 'Thể loại nhấn mạnh vào yếu tố nghệ thuật, họa sĩ hoặc phong cách vẽ đặc trưng.', 1),
(43, 'Big Breasts', 'big-breasts', 'Thể loại tập trung vào các nhân vật nữ có vòng một lớn (tương tự thể loại \"Vếu To\").', 1),
(44, 'Big Dick', 'big-dick', 'Thể loại tập trung vào các nhân vật nam có kích thước bộ phận sinh dục lớn.', 1),
(45, 'Blowjob', 'blowjob', 'Thể loại có chứa hành vi quan hệ tình dục bằng miệng.', 1),
(46, 'Full Color', 'full-color', 'Thể loại truyện được tô màu toàn bộ, thay vì hai màu đen trắng truyền thống.', 0),
(47, 'Milf', 'milf', 'Thể loại tập trung vào các nhân vật nữ là những người mẹ hoặc phụ nữ trưởng thành, quyến rũ.', 1),
(48, 'Uncensored', 'uncensored', 'Thể loại nội dung người lớn không bị che, không có các vệt mờ hay thanh chắn bảo hộ.', 0),
(49, 'Âu Cổ', 'au-co', '', 0),
(50, 'Cổ Đại', 'co-dai', '', 0),
(51, 'Con Gái', 'con-gai', '', 0),
(52, 'Cưới Trước Yêu Sau', 'cuoi-truoc-yeu-sau', '', 0),
(53, 'Lãng Mạn', 'lang-man', '', 0),
(54, 'Manhwa', 'manhwa', 'Thể loại truyện tranh có nguồn gốc từ Hàn Quốc.', 0),
(55, 'Ngôn Tình', 'ngon-tinh', '', 0),
(56, 'Adult', 'adult', 'Thể loại dành riêng cho người lớn, chứa nội dung nhạy cảm hoặc mang tính chất trưởng thành sâu sắc.', 0),
(57, 'Drama', 'drama', 'Thể loại tập trung vào những tình huống kịch tính, xung đột tâm lý gay gắt và các biến cố trong cuộc sống.', 1),
(58, 'Josei', 'josei', 'Thể loại truyện hướng tới đối tượng độc giả là phụ nữ trưởng thành, thường khai thác thực tế cuộc sống và tình yêu.', 1),
(59, 'Mature', 'mature', 'Thể loại có nội dung trưởng thành, chín chắn, có thể bao gồm các yếu tố bạo lực nhẹ hoặc tình cảm sâu sắc của người lớn.', 1),
(60, 'Ntr', 'ntr', 'Thể loại có cốt truyện xoay quanh việc nhân vật bị người yêu hoặc bạn đời phản bội, cướp mất bởi người khác.', 1),
(61, 'Romance', 'romance', 'Thể loại tập trung vào câu chuyện tình yêu lãng mạn và sự phát triển tình cảm giữa các nhân vật.', 1),
(62, 'Ahegao', 'ahegao', 'Thể loại mô tả biểu cảm gương mặt cường điệu, phấn khích tột độ của nhân vật khi đạt khoái cảm trong nội dung người lớn.', 1),
(63, 'Ecchi', 'ecchi', 'Thể loại chứa các yếu tố gợi cảm, quyến rũ hoặc tình huống nhạy cảm ở mức độ nhẹ, mang tính hài hước.', 1),
(64, 'Harem', 'harem', 'Thể loại cốt truyện xoay quanh một nhân chính được nhiều nhân vật khác giới xung quanh yêu mến và theo đuổi.', 1),
(65, 'Hiện Đại', 'hien-dai', '', 0),
(66, 'Smut', 'smut', 'Thể loại truyện lãng mạn có chứa các cảnh mô tả chi tiết, rõ ràng về quan hệ tình dục của người lớn.', 1),
(67, 'Tình Cảm', 'tinh-cam', '', 0),
(68, 'Truyện Màu', 'truyen-mau', '', 0),
(69, 'Webtoon', 'webtoon', 'Thể loại truyện tranh được thiết kế chuyên biệt để đọc bằng cách cuộn dọc trên các thiết bị kỹ thuật số.', 0),
(70, 'Anal', 'anal', 'Thể loại có chứa hành vi quan hệ tình dục qua đường hậu môn.', 1),
(71, 'Double Penetration', 'double-penetration', 'Thể loại có chứa hành vi quan hệ tình dục thâm nhập kép (đồng thời từ hai phía).', 1),
(72, 'Tự Sướng', 'tu-suong', '', 0),
(73, 'Big Ass', 'big-ass', 'Thể loại tập trung vào các nhân vật có vòng ba lớn, nảy nở.', 1),
(74, 'Big Boobs', 'big-boobs', 'Thể loại tập trung vào các nhân vật nữ có vòng một lớn (đồng nghĩa với Big Breasts, Ngực Lớn).', 0),
(75, 'Big Penis', 'big-penis', 'Thể loại tập trung vào nhân vật nam có kích thước bộ phận sinh dục lớn (đồng nghĩa với Big Dick).', 0),
(76, 'Comedy', 'comedy', 'Thể loại chứa các tình huống hài hước, gây cười và mang tính chất giải trí nhẹ nhàng.', 1),
(77, 'Comic 18+', 'comic-18', 'Thể loại truyện tranh có chứa các nội dung nhạy cảm, bạo lực hoặc tình dục dành cho người lớn.', 0),
(78, 'Hài Hước', 'hai-huoc', '', 0),
(79, 'Hentai', 'hentai', 'Thể loại hoạt hình hoặc truyện tranh Nhật Bản có chứa nội dung tình dục rõ rệt của người lớn.', 0),
(80, 'Hentaivn', 'hentaivn', 'Thuật ngữ thường dùng để chỉ các nội dung Hentai được dịch thuật hoặc đăng tải hướng tới cộng đồng độc giả Việt Nam.', 0),
(81, 'Ngực Lớn', 'nguc-lon', '', 0),
(82, 'Truyện Tranh', 'truyen-tranh', '', 0),
(83, 'Comic', 'comic', 'Thể loại truyện tranh nói chung (thường dùng để chỉ truyện tranh phong cách Âu Mỹ hoặc các nền văn hóa khác).', 1),
(84, 'Truyện Dài', 'truyen-dai', '', 0),
(85, 'Echi', 'echi', 'Cách viết biến tấu khác của thể loại Ecchi, chứa các yếu tố gợi cảm hoặc tình huống nhạy cảm nhẹ nhàng.', 0),
(86, 'Fantasy', 'fantasy', 'Thể loại có bối cảnh giả tưởng, chứa các yếu tố kỳ ảo, phép thuật, quái vật hoặc thế giới không có thực.', 1),
(87, 'Hentai Màu', 'hentai-mau', '', 0),
(88, 'Beast', 'beast', 'Thể loại có sự xuất hiện của các nhân vật mang hình dáng hoặc có đặc tính của động vật, thú nhân.', 0),
(89, 'Cốt Truyện', 'cot-truyen', '', 0),
(90, 'Elf', 'elf', 'Thể loại giả tưởng có nhân vật là tiên tộc, thường được miêu tả với đôi tai nhọn, dung mạo xinh đẹp và có phép thuật.', 1),
(91, 'Funny', 'funny', 'Thể loại mang yếu tố hài hước, gây cười (tương đồng với thể loại Comedy/Hài hước).', 0),
(92, 'Mind Break', 'mind-break', 'Thể loại mô tả tình trạng tâm lý của nhân vật bị suy sụp, mất tự chủ hoặc phá vỡ hoàn toàn do áp lực tột độ.', 1),
(93, 'Mind Control', 'mind-control', 'Thể loại chứa yếu tố thao túng tâm lý, thôi miên hoặc kiểm soát hoàn toàn trí não và hành vi của nhân vật khác.', 1),
(94, 'Nô Lệ', 'no-le', '', 0),
(95, 'Series', 'series', 'Thể loại truyện hoặc tác phẩm dài kỳ, được chia thành nhiều tập hoặc phần nối tiếp nhau.', 1),
(96, 'Slave', 'slave', 'Thể loại có cốt truyện xoay quanh các nhân vật là nô lệ, người hầu hoặc bị ép buộc phục tùng (đồng nghĩa với Nô Lệ).', 1),
(97, 'Story Arc', 'story-arc', 'Thuật ngữ chỉ một chuỗi các chương truyện liên tiếp nhau cùng giải quyết một sự kiện hoặc mâu thuẫn cụ thể trong tổng thể cốt truyện.', 1),
(98, 'Succubus', 'succubus', 'Thể loại có sự xuất hiện của nữ ác ma, thường dùng vẻ đẹp và sự quyến rũ để mê hoặc, hút sinh lực của nam giới.', 1),
(99, 'Three Some', 'three-some', 'Thể loại có chứa các cảnh quan hệ tình dục với sự tham gia của ba người cùng một lúc.', 1),
(100, 'Thú Vật', 'thu-vat', '', 0),
(101, 'Xúc Tua', 'xuc-tua', '', 0),
(102, 'Monster', 'monster', 'Thể loại giả tưởng có sự xuất hiện của các sinh vật quái vật, dị hình hoặc sinh vật huyền bí.', 1),
(103, 'Breast Sucking', 'breast-sucking', 'Thể loại có chứa hành vi mút, bú ngực nhân vật nữ.', 1),
(104, 'Hentai Cube', 'hentai-cube', 'Thuật ngữ thường dùng để chỉ một nền tảng hoặc định dạng lưu trữ, đăng tải nội dung hoạt hình/truyện tranh người lớn.', 0),
(105, 'Hentai Không Che', 'hentai-khong-che', '', 0),
(106, 'Ihentai', 'ihentai', 'Tên của một trang web hoặc nền tảng trực tuyến phổ biến chuyên chia sẻ truyện tranh người lớn.', 0),
(107, 'Nữ Sinh', 'nu-sinh', '', 0),
(108, 'Paizuri', 'paizuri', 'Thuật ngữ chỉ hành vi quan hệ tình dục bằng cách dùng hai bầu ngực kẹp và chà xát xung quanh bộ phận sinh dục nam.', 1),
(109, 'Bạo Dâm', 'bao-dam', '', 0),
(110, 'Bdsm', 'bdsm', 'Thể loại liên quan đến các hành vi tình dục có yếu tố ràng buộc, kỷ luật, thống trị, quy phục, bạo dâm và khổ dâm.', 1),
(111, 'Giáo Viên', 'giao-vien', '', 0),
(112, 'Teacher', 'teacher', 'Thể loại tập trung vào mối quan hệ liên quan đến giáo viên (đồng nghĩa với Giáo Viên).', 1),
(113, 'Cổ Trang', 'co-trang', '', 0),
(114, 'Manga', 'manga', 'Thể loại truyện tranh có nguồn gốc từ Nhật Bản.', 0),
(115, 'Hentai Lxmanga', 'hentai-lxmanga', 'Thuật ngữ chỉ chuyên mục hoặc các nội dung Hentai được đăng tải trên nền tảng Lxmanga.', 0),
(116, 'Hentaicb', 'hentaicb', 'Tên viết tắt hoặc ký hiệu thường dùng để chỉ nền tảng Hentai Cube.', 0),
(117, 'Hentaihvn', 'hentaihvn', 'Tên một nền tảng hoặc trang web trực tuyến chuyên chia sẻ nội dung Hentai.', 0),
(118, 'Hentaivl', 'hentaivl', 'Tên một trang web trực tuyến phổ biến chuyên đăng tải và chia sẻ truyện tranh người lớn.', 0),
(119, 'Hentaivnx', 'hentaivnx', 'Tên một nền tảng hoặc cộng đồng dịch thuật, chia sẻ nội dung Hentai tại Việt Nam.', 0),
(120, 'Hentaiz', 'hentaiz', 'Tên một trang web hoặc kênh trực tuyến chuyên cập nhật các bộ truyện tranh người lớn.', 0),
(121, 'Manhua', 'manhua', 'Thể loại truyện tranh có nguồn gốc từ Trung Quốc, Đài Loan hoặc Hồng Kông.', 0),
(122, 'Mimihentai', 'mimihentai', 'Tên của một nền tảng web trực tuyến chuyên đăng tải các nội dung truyện tranh 18+.', 0),
(123, 'Oneshot', 'oneshot', 'Thể loại truyện ngắn chỉ gói gọn trong duy nhất một chương (chương đơn) và kết thúc.', 1),
(124, 'Rphang', 'rphang', 'Tên của một nhóm dịch hoặc nền tảng trực tuyến chuyên chia sẻ, đăng tải các sản phẩm truyện tranh người lớn.', 0),
(125, 'Sayhentai', 'sayhentai', 'Tên của một nền tảng hoặc trang web trực tuyến phổ biến chuyên đăng tải và cập nhật nội dung truyện tranh 18+.', 0),
